//! Linux-compatible ext4 directory hashing (fs/ext4/hash.c).
use crate::Error;
pub const DX_HASH_LEGACY:u8=0; pub const DX_HASH_HALF_MD4:u8=1; pub const DX_HASH_TEA:u8=2;
pub const DX_HASH_LEGACY_UNSIGNED:u8=3; pub const DX_HASH_HALF_MD4_UNSIGNED:u8=4;
pub const DX_HASH_TEA_UNSIGNED:u8=5; pub const DX_HASH_SIPHASH:u8=6;
#[derive(Clone,Copy,Debug,PartialEq,Eq)] pub struct DirectoryHash{pub major:u32,pub minor:u32}
fn legacy(name:&[u8],signed:bool)->u32{let(mut a,mut b)=(0x12a3_fe2du32,0x37ab_e8f9u32);for &c in name{let x=if signed{c as i8 as i32 as u32}else{c as u32};let mut h=b.wrapping_add(a^(x.wrapping_mul(7_152_373)));if h&0x8000_0000!=0{h=h.wrapping_sub(0x7fff_ffff)}b=a;a=h;}a.wrapping_shl(1)&!1}
fn words(name:&[u8],n:usize,signed:bool)->[u32;8]{let mut o=[0u32;8];let len=name.len().min(n*4);let p=(name.len() as u32&255)|((name.len() as u32&255)<<8);let p=p|(p<<16);let mut i=0;let mut j=0;while i+4<=len{let cv=|b:u8|if signed{b as i8 as i32 as u32}else{b as u32};o[j]=(cv(name[i])<<24).wrapping_add(cv(name[i+1])<<16).wrapping_add(cv(name[i+2])<<8).wrapping_add(cv(name[i+3]));i+=4;j+=1;}let mut v=p;while i<len{let b=if signed{name[i] as i8 as i32 as u32}else{name[i] as u32};v=b.wrapping_add(v<<8);i+=1;}if j<n{o[j]=v;j+=1;}while j<n{o[j]=p;j+=1;}o}
fn md4(s:&mut[u32;4],x:&[u32;8]){fn f(x:u32,y:u32,z:u32)->u32{z^(x&(y^z))}fn g(x:u32,y:u32,z:u32)->u32{(x&y).wrapping_add((x^y)&z)}fn h(x:u32,y:u32,z:u32)->u32{x^y^z}macro_rules! r{($a:ident,$b:ident,$c:ident,$d:ident,$x:expr,$k:expr,$n:expr,$f:ident)=>{{$a=$a.wrapping_add($f($b,$c,$d)).wrapping_add($x).wrapping_add($k).rotate_left($n);}}}let(mut a,mut b,mut c,mut d)=(s[0],s[1],s[2],s[3]);r!(a,b,c,d,x[0],0,3,f);r!(d,a,b,c,x[1],0,7,f);r!(c,d,a,b,x[2],0,11,f);r!(b,c,d,a,x[3],0,19,f);r!(a,b,c,d,x[4],0,3,f);r!(d,a,b,c,x[5],0,7,f);r!(c,d,a,b,x[6],0,11,f);r!(b,c,d,a,x[7],0,19,f);let k=0x5a82_7999;r!(a,b,c,d,x[1],k,3,g);r!(d,a,b,c,x[3],k,5,g);r!(c,d,a,b,x[5],k,9,g);r!(b,c,d,a,x[7],k,13,g);r!(a,b,c,d,x[0],k,3,g);r!(d,a,b,c,x[2],k,5,g);r!(c,d,a,b,x[4],k,9,g);r!(b,c,d,a,x[6],k,13,g);let k=0x6ed9_eba1;r!(a,b,c,d,x[3],k,3,h);r!(d,a,b,c,x[7],k,9,h);r!(c,d,a,b,x[2],k,11,h);r!(b,c,d,a,x[6],k,15,h);r!(a,b,c,d,x[1],k,3,h);r!(d,a,b,c,x[5],k,9,h);r!(c,d,a,b,x[0],k,11,h);r!(b,c,d,a,x[4],k,15,h);s[0]=s[0].wrapping_add(a);s[1]=s[1].wrapping_add(b);s[2]=s[2].wrapping_add(c);s[3]=s[3].wrapping_add(d);}
fn tea(s:&mut[u32;4],x:&[u32;8]){let(mut a,mut b)=(s[0],s[1]);let mut sum=0u32;for _ in 0..16{sum=sum.wrapping_add(0x9e37_79b9);a=a.wrapping_add((b.wrapping_shl(4).wrapping_add(x[0]))^(b.wrapping_add(sum))^(b.wrapping_shr(5).wrapping_add(x[1])));b=b.wrapping_add((a.wrapping_shl(4).wrapping_add(x[2]))^(a.wrapping_add(sum))^(a.wrapping_shr(5).wrapping_add(x[3])));}s[0]=s[0].wrapping_add(a);s[1]=s[1].wrapping_add(b);}
fn sipround(v:&mut[u64;4]){v[0]=v[0].wrapping_add(v[1]);v[1]=v[1].rotate_left(13);v[1]^=v[0];v[0]=v[0].rotate_left(32);v[2]=v[2].wrapping_add(v[3]);v[3]=v[3].rotate_left(16);v[3]^=v[2];v[0]=v[0].wrapping_add(v[3]);v[3]=v[3].rotate_left(21);v[3]^=v[0];v[2]=v[2].wrapping_add(v[1]);v[1]=v[1].rotate_left(17);v[1]^=v[2];v[2]=v[2].rotate_left(32)}
pub fn siphash24(key:[u64;2],m:&[u8])->u64{let(k0,k1)=(key[0],key[1]);let mut v=[0x736f_6d65_7073_6575^k0,0x646f_7261_6e64_6f6d^k1,0x6c79_6765_6e65_7261^k0,0x7465_6462_7974_6573^k1];let mut chunks=m.chunks_exact(8);for c in &mut chunks{let x=u64::from_le_bytes([c[0],c[1],c[2],c[3],c[4],c[5],c[6],c[7]]);v[3]^=x;sipround(&mut v);sipround(&mut v);v[0]^=x;}let rem=chunks.remainder();let mut last=(m.len() as u64)<<56;for(i,b)in rem.iter().enumerate(){last|=(*b as u64)<<(i*8);}v[3]^=last;sipround(&mut v);sipround(&mut v);v[0]^=last;v[2]^=255;for _ in 0..4{sipround(&mut v);}v[0]^v[1]^v[2]^v[3]}
/// SipHash requires the fscrypt directory key; it is never inferred from s_hash_seed.
pub fn hash_directory_name(version:u8,seed:[u32;4],name:&[u8],sipkey:Option<[u64;2]>)->Result<DirectoryHash,Error>{if name.len()>255||name.iter().any(|b|*b==0||*b==b'/'){return Err(Error::InvalidDirectoryEntry)}let(major,minor)=match version{0=>(legacy(name,true),0),3=>(legacy(name,false),0),1|2|4|5=>{let signed=version==1||version==2;let width=if version==1||version==4{32}else{16};let mut s=if seed.iter().all(|v|*v==0){[0x6745_2301,0xefcd_ab89,0x98ba_dcfe,0x1032_5476]}else{seed};for offset in (0..name.len()).step_by(width){let x=words(&name[offset..],width/4,signed);if width==32{md4(&mut s,&x)}else{tea(&mut s,&x)}}if width==32{(s[1],s[2])}else{(s[0],s[1])}},6=>{let v=siphash24(sipkey.ok_or(Error::UnsupportedFormat)?,name);((v>>32)as u32,v as u32)},_=>return Err(Error::UnsupportedFormat)};let mut major=major&!1;if major==0xffff_fffe{major=0xffff_fffc}Ok(DirectoryHash{major,minor})}
pub fn ext4_directory_hash_seed(sb:&[u8])->Result<[u32;4],Error>{if sb.len()<1024{return Err(Error::Truncated)}let mut s=[0u32;4];for i in 0..4{s[i]=u32::from_le_bytes(sb[236+i*4..240+i*4].try_into().map_err(|_|Error::Truncated)?)}Ok(s)}
#[cfg(test)]mod tests{use super::*;#[test]fn siphash_reference_vectors(){let k=[0x0706_0504_0302_0100,0x0f0e_0d0c_0b0a_0908];assert_eq!(siphash24(k,&[]),0x726f_db47_dd0e_0e31);assert_eq!(siphash24(k,&[0]),0x74f8_39c5_93dc_67fd);}#[test]fn supported_hashes_produce_even_major(){for v in 0..=5{assert_eq!(hash_directory_name(v,[1,2,3,4],b"hello",None).unwrap().major&1,0);}assert!(hash_directory_name(6,[0;4],b"hello",None).is_err());}}
